import asyncio


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently from synchronous code, returning results in input order.
    Any coroutine not finishing within `seconds` is cancelled and its result is None.
    Can be called repeatedly in the same process."""
    async def _run_all_with_deadline(coros, timeout):
        tasks = [asyncio.create_task(c) for c in coros]
        done, pending = await asyncio.wait(tasks, timeout=timeout)
        # Cancel all pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion to suppress warnings
        await asyncio.gather(*pending, return_exceptions=True)
        # Collect results in input order, None for cancelled or errored tasks
        results = []
        for task in tasks:
            if task.done():
                try:
                    results.append(task.result())
                except asyncio.CancelledError:
                    results.append(None)
                except Exception:
                    results.append(None)
            else:
                results.append(None)
        return results

    loop = asyncio.get_event_loop()
    return loop.run_until_complete(_run_all_with_deadline(coros, seconds))

