import asyncio
from async_bridge import run_sync, with_timeout


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently, returning results in input order.
    Any coroutine not finishing within `seconds` is cancelled and replaced with None."""
    async def _main():
        # Wrap each coroutine with timeout
        wrapped = [with_timeout(coro, seconds, default=None) for coro in coros]
        return await asyncio.gather(*wrapped)

    return run_sync(_main())
